export type AuditControllerListV1Params = {
/**
 * @minimum 1
 * @maximum 1000000
 */
page?: number;
/**
 * @minimum 1
 * @maximum 2000
 */
limit?: number;
/**
 * P13-09 — omit for the paginated JSON envelope. When set, the route ignores page/limit/cursor and returns every row matching the other filters as a CSV or newline-delimited-JSON file instead, capped at 50,000 rows (`X-Export-Truncated: true` when the cap was hit).
 */
format?: AuditControllerListV1Format;
entity?: string;
search?: string;
/**
 * URL-encoded JSON. Root must be `$and`; each entry maps exactly one field to exactly one operator — the grammar is flat and cannot nest.
 *
 * Example: `{ "$and": [ { "action": { "$contains": "approved" } } ] }`
 *
 * Allowed fields and their operators:
 * - `entity` (string): $eq, $ne, $in, $notIn, $null, $notNull, $contains, $notContains, $startsWith, $endsWith
 * - `action` (string): $eq, $ne, $in, $notIn, $null, $notNull, $contains, $notContains, $startsWith, $endsWith
 * - `createdAt` (datetime): $eq, $ne, $in, $notIn, $null, $notNull, $gte, $lte, $gt, $lt
 * - `userId` (string): $eq, $ne, $in, $notIn, $null, $notNull, $contains, $notContains, $startsWith, $endsWith
 *
 * Limits: at most 32 conditions per request, and at most 200 values in an `$in`/`$notIn` list. Exceeding either is a 400, as is an unknown field or operator.
 */
filters?: string;
/**
 * Comma-separated field:asc|desc (allowlisted fields)
 */
sort?: string;
/**
 * Opaque keyset cursor from a previous response's `meta.nextCursor` (P6-08). When set, `page` is ignored and `meta.page` comes back null — a cursor resumes a position, it is not on page N of anything. Requires a single sort field; a multi-field `sort` with a cursor is a 400. Use it for a list being scrolled while rows are inserted: offset paging shifts the window and silently skips or repeats rows.
 */
cursor?: string;
};

