export const getReviewReportsControllerListV1Url = (projectId: string,
    params: ReviewReportsControllerListV1Params,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/projects/${projectId}/review-reports?${stringifiedParams}` : `/api/v1/projects/${projectId}/review-reports`
}

